#include <assert.h>
#include <stdint.h>

#include <gnutls/gnutls.h>
#include <gnutls/pkcs12.h>

#include "fuzzer.h"

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
        gnutls_datum_t raw = {(unsigned char*)data, (unsigned int)size};
        gnutls_pkcs12_t p12;
        gnutls_x509_privkey_t key;
        gnutls_x509_crt_t *chain;
        gnutls_x509_crt_t *extras;
        gnutls_x509_crl_t crl;
        unsigned int chain_len = 0, extras_len = 0;
        int ret;

        raw.data = (unsigned char *)data;
        raw.size = size;

        ret = gnutls_pkcs12_init(&p12);
        assert(ret >= 0);

        ret = gnutls_pkcs12_import(p12, &raw, GNUTLS_X509_FMT_DER, 0);
        if (ret < 0) {
                goto cleanup;
        }

        /* catch crashes */
        gnutls_pkcs12_verify_mac(p12, "1234");

        ret = gnutls_pkcs12_simple_parse(p12, "1234", &key, &chain, &chain_len, &extras, &extras_len, &crl, 0);
        if (ret >= 0) {
                gnutls_x509_privkey_deinit(key);
                if (crl)
                        gnutls_x509_crl_deinit(crl);
                if (extras_len > 0) {
                        for (unsigned i = 0; i < extras_len; i++)
                                gnutls_x509_crt_deinit(extras[i]);
                        gnutls_free(extras);
                }
                if (chain_len > 0) {
                        for (unsigned i = 0; i < chain_len; i++)
                                gnutls_x509_crt_deinit(chain[i]);
                        gnutls_free(chain);
                }
        }

cleanup:
        gnutls_pkcs12_deinit(p12);
        return 0;
}

gnutls_pkcs12_simple_parse(gnutls_pkcs12_t p12,
                           const char *password,
                           gnutls_x509_privkey_t * key,
                           gnutls_x509_crt_t ** chain,
                           unsigned int *chain_len,
                           gnutls_x509_crt_t ** extra_certs,
                           unsigned int *extra_certs_len,
                           gnutls_x509_crl_t * crl, unsigned int flags)
{
        gnutls_pkcs12_bag_t bag = NULL;
        gnutls_x509_crt_t *_extra_certs = NULL;
        unsigned int _extra_certs_len = 0;
        gnutls_x509_crt_t *_chain = NULL;
        unsigned int _chain_len = 0;
        int idx = 0;
        int ret;
        size_t cert_id_size = 0;
        size_t key_id_size = 0;
        uint8_t cert_id[20];
        uint8_t key_id[20];
        int privkey_ok = 0;
        unsigned int i;
        int elements_in_bag;

        *key = NULL;

        if (crl)
                *crl = NULL;

        /* find the first private key */
        for (;;) {

                ret = gnutls_pkcs12_bag_init(&bag);
                if (ret < 0) {
                        bag = NULL;
                        gnutls_assert();
                        goto done;
                }

                ret = gnutls_pkcs12_get_bag(p12, idx, bag);
                if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
                        gnutls_pkcs12_bag_deinit(bag);
                        bag = NULL;
                        break;
                }
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }

                ret = gnutls_pkcs12_bag_get_type(bag, 0);
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }

                if (ret == GNUTLS_BAG_ENCRYPTED) {
                        if (password == NULL) {
                                ret =
                                    gnutls_assert_val
                                    (GNUTLS_E_DECRYPTION_FAILED);
                                goto done;
                        }

                        ret = gnutls_pkcs12_bag_decrypt(bag, password);
                        if (ret < 0) {
                                gnutls_assert();
                                goto done;
                        }
                }

                elements_in_bag = gnutls_pkcs12_bag_get_count(bag);
                if (elements_in_bag < 0) {
                        gnutls_assert();
                        goto done;
                }

                for (i = 0; i < (unsigned)elements_in_bag; i++) {
                        int type;
                        gnutls_datum_t data;

                        type = gnutls_pkcs12_bag_get_type(bag, i);
                        if (type < 0) {
                                gnutls_assert();
                                goto done;
                        }

                        ret = gnutls_pkcs12_bag_get_data(bag, i, &data);
                        if (ret < 0) {
                                gnutls_assert();
                                goto done;
                        }

                        switch (type) {
                        case GNUTLS_BAG_PKCS8_ENCRYPTED_KEY:
                                if (password == NULL) {
                                        ret =
                                            gnutls_assert_val
                                            (GNUTLS_E_DECRYPTION_FAILED);
                                        goto done;
                                }

                                FALLTHROUGH;
                        case GNUTLS_BAG_PKCS8_KEY:
                                if (*key != NULL) {     /* too simple to continue */
                                        gnutls_assert();
                                        break;
                                }

                                ret = gnutls_x509_privkey_init(key);
                                if (ret < 0) {
                                        gnutls_assert();
                                        goto done;
                                }

                                ret = gnutls_x509_privkey_import_pkcs8
                                    (*key, &data, GNUTLS_X509_FMT_DER,
                                     password,
                                     type ==
                                     GNUTLS_BAG_PKCS8_KEY ?
                                     GNUTLS_PKCS_PLAIN : 0);
                                if (ret < 0) {
                                        gnutls_assert();
                                        goto done;
                                }

                                key_id_size = sizeof(key_id);
                                ret =
                                    gnutls_x509_privkey_get_key_id(*key, 0,
                                                                   key_id,
                                                                   &key_id_size);
                                if (ret < 0) {
                                        gnutls_assert();
                                        goto done;
                                }

                                privkey_ok = 1; /* break */
                                break;
                        default:
                                break;
                        }
                }

                idx++;
                gnutls_pkcs12_bag_deinit(bag);
                bag = NULL;

                if (privkey_ok != 0)    /* private key was found */
                        break;
        }

        if (privkey_ok == 0) {  /* no private key */
                gnutls_assert();
                return GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
        }

